import{f as e,o as s,c as n,a2 as o}from"./chunks/framework.BUDOXiIz.js";const m=JSON.parse('{"title":"CoopApps — Cuántos usuarios y qué tan rápido","description":"","frontmatter":{},"headers":[],"relativePath":"presentacion-stakeholders/usuarios-y-rendimiento-para-imagenes.md","filePath":"presentacion-stakeholders/usuarios-y-rendimiento-para-imagenes.md","lastUpdated":null}'),i={name:"presentacion-stakeholders/usuarios-y-rendimiento-para-imagenes.md"};function t(r,a,l,p,d,c){return s(),n("div",null,[...a[0]||(a[0]=[o(`<h1 id="coopapps-—-cuantos-usuarios-y-que-tan-rapido" tabindex="-1">CoopApps — Cuántos usuarios y qué tan rápido <a class="header-anchor" href="#coopapps-—-cuantos-usuarios-y-que-tan-rapido" aria-label="Permalink to &quot;CoopApps — Cuántos usuarios y qué tan rápido&quot;">​</a></h1><p>Una imagen que muestra la capacidad y la velocidad del sistema en números: cuántos socios, empleados y técnicos soporta, y en cuántos segundos responde. Todos los datos salen de la especificación; ninguno promete algo que no esté escrito.</p><table tabindex="0"><thead><tr><th>Dato</th><th>Valor</th></tr></thead><tbody><tr><td>Fecha</td><td>10-11-2026</td></tr><tr><td>Fuentes</td><td><code>docs/especificacion/anexos/T08-NFR-no-funcionales-seguridad.md</code> §7.1 (perfil de carga de referencia, DEC-075), §7.2 (tiempos de respuesta, RNF-NFR-001 a RNF-NFR-008), §7.3 (procesos masivos, RNF-NFR-010 a RNF-NFR-016), RNF-NFR-021 (separación de cargas) y RNF-NFR-030 (disponibilidad, DEC-063); <code>02-preguntas-abiertas.md</code> PA-NFR-04</td></tr><tr><td>Carácter</td><td><strong>Metas de diseño, no mediciones.</strong> El perfil de carga es la referencia para construir y probar desde la ola O0 y se recalibra con lo que se mida en la cooperativa piloto</td></tr><tr><td>Datos</td><td>Todos los nombres de ejemplo son ficticios</td></tr></tbody></table><hr><h2 id="_0-como-usar-este-documento" tabindex="-1">0. Cómo usar este documento <a class="header-anchor" href="#_0-como-usar-este-documento" aria-label="Permalink to &quot;0. Cómo usar este documento&quot;">​</a></h2><ol><li>Puede usarse en la misma conversación que <code>lo-esencial-para-imagenes.md</code>. Si ya pegaste el prompt de estilo de ese documento, saltá directo al pedido.</li><li>Si la conversación es nueva, pegar primero el prompt de la sección 0.1.</li><li>Pedir la imagen por código: &quot;Generá IMG-R01&quot;.</li><li>La imagen trae una <strong>frase para decir</strong> en voz alta mientras se muestra.</li></ol><h3 id="_0-1-prompt-de-estilo-pegar-primero" tabindex="-1">0.1 Prompt de estilo (pegar primero) <a class="header-anchor" href="#_0-1-prompt-de-estilo-pegar-primero" aria-label="Permalink to &quot;0.1 Prompt de estilo (pegar primero)&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Vas a dibujar una diapositiva para una reunión con directivos y stakeholders de trayectoria, de una empresa de software para cooperativas de servicios públicos de Argentina. La diapositiva muestra la capacidad y la velocidad del sistema con cifras concretas.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>El tono es seguro y sereno: el de alguien que ya hizo el trabajo y lo muestra. Nada de adjetivos vacíos (&quot;revolucionario&quot;, &quot;increíble&quot;, &quot;ultrarrápido&quot;, &quot;el mejor&quot;), nada de signos de exclamación, nada de lenguaje publicitario. La fuerza está en el número.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Reglas obligatorias:</span></span>
<span class="line"><span>1. Usá SOLO los textos y números del documento. No inventes cifras, comparaciones ni promesas. Podés acortar sin cambiar el sentido.</span></span>
<span class="line"><span>2. Texto visible en español de Argentina.</span></span>
<span class="line"><span>3. Generá la imagen con código (HTML con SVG en Claude; Python con matplotlib en ChatGPT), 1920×1080 px. No uses el generador de imágenes para nada que tenga texto.</span></span>
<span class="line"><span>4. Paleta: gris carbón #2F343A, gris medio #6B7280, gris claro #E5E7EB, blanco #FFFFFF y verde cooperativo #2E7D32 como único acento. Sin rojo.</span></span>
<span class="line"><span>5. Composición limpia: mucho espacio en blanco, un título grande (64 a 80 px), las cifras dominan. Texto mínimo de 20 px.</span></span>
<span class="line"><span>6. Tipografía sans serif limpia (Inter o similar), con peso fuerte en títulos y cifras.</span></span>
<span class="line"><span>7. Íconos de línea simples. Nada de robots, cohetes, velocímetros exagerados ni efectos futuristas.</span></span>
<span class="line"><span>8. Después de la imagen, listá qué datos del documento usaste.</span></span>
<span class="line"><span>Esperá mi pedido por código (IMG-R01).</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><hr><h2 id="_1-ficha-y-prompt" tabindex="-1">1. Ficha y prompt <a class="header-anchor" href="#_1-ficha-y-prompt" aria-label="Permalink to &quot;1. Ficha y prompt&quot;">​</a></h2><h3 id="img-r01-—-cuantos-usuarios-y-que-tan-rapido" tabindex="-1">IMG-R01 — Cuántos usuarios y qué tan rápido. <a class="header-anchor" href="#img-r01-—-cuantos-usuarios-y-que-tan-rapido" aria-label="Permalink to &quot;IMG-R01 — Cuántos usuarios y qué tan rápido.&quot;">​</a></h3><p><strong>Respaldo (T08 §7, perfil de carga de referencia adoptado por DEC-075):</strong></p><p>Cantidad, por cooperativa y en toda la plataforma (diseño para 100 cooperativas, escalable a 300 sin rediseñar):</p><table tabindex="0"><thead><tr><th>Dimensión</th><th>Cooperativa estándar</th><th>Cooperativa grande</th><th>Plataforma (100 cooperativas)</th></tr></thead><tbody><tr><td>Suministros activos</td><td>25.000</td><td>150.000</td><td>3.000.000</td></tr><tr><td>Personas o titulares</td><td>20.000</td><td>120.000</td><td>2.400.000</td></tr><tr><td>Comprobantes por mes</td><td>30.000</td><td>180.000</td><td>3.600.000</td></tr><tr><td>Empleados usando el sistema a la vez</td><td>30</td><td>150</td><td>2.088</td></tr><tr><td>Socios activos el día pico de vencimiento</td><td>5.000</td><td>30.000</td><td>360.000</td></tr><tr><td>Técnicos y lecturistas en la calle a la vez</td><td>10</td><td>60</td><td>720</td></tr></tbody></table><p>Con 300 cooperativas, la plataforma llega a 9 millones de suministros y 6.264 empleados conectados a la vez, sin rediseño. El pico de la plataforma no es la suma de los picos de cada cooperativa, porque sus vencimientos no coinciden.</p><p>Velocidad, medida al 100 % de la carga pico (en el 95 % de los casos):</p><ul><li>abrir una ficha: 0,2 segundos;</li><li>buscar un socio por documento, nombre, domicilio o medidor: 0,5 segundos en una cooperativa grande;</li><li>cobrar en caja: 0,8 segundos, con el recibo listo para imprimir en 2 segundos y 30 cajas cobrando a la vez;</li><li>ficha completa del socio con su cuenta corriente: 1 segundo;</li><li>app del socio en un celular de gama baja con 4G lenta: la pantalla útil aparece en 2,5 segundos.</li></ul><p>Procesos masivos:</p><ul><li>facturar 50.000 suministros: 60 minutos o menos;</li><li>autorizar en ARCA ese lote: 2 horas o menos, si ARCA responde normal;</li><li>generar los PDF y distribuirlos: 1 hora y 4 horas;</li><li>en una jornada se factura, se autoriza y se distribuye.</li></ul><p>Reglas:</p><ul><li>lo pesado de una cooperativa no frena a las demás: un proceso masivo saturado sube como máximo un 10 % el tiempo de las pantallas;</li><li>si una pantalla no llega a su meta, se convierte en un proceso con barra de progreso en lugar de relajar la meta;</li><li>cada meta tiene su prueba de carga automática, y la entrega no sale si no la cumple;</li><li>disponibilidad del 99,5 % mensual.</li></ul><p><strong>Frase para decir:</strong> &quot;No le decimos &#39;es rápido&#39;. Le decimos cuántos segundos, con cuánta gente conectada, y lo probamos en cada entrega.&quot;</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Generá IMG-R01 con código.</span></span>
<span class="line"><span>Título grande: &quot;Cuántos usuarios y qué tan rápido.&quot;</span></span>
<span class="line"><span>Composición en dos mitades:</span></span>
<span class="line"><span>- Izquierda, &quot;Cuántos&quot;: tres columnas de cifras grandes, &quot;Cooperativa estándar&quot;, &quot;Cooperativa grande&quot; y, más destacada en verde, &quot;Plataforma · 100 cooperativas&quot;. Filas con rótulo a la izquierda:</span></span>
<span class="line"><span>  &quot;Suministros activos&quot;: 25.000 · 150.000 · 3.000.000</span></span>
<span class="line"><span>  &quot;Empleados conectados a la vez&quot;: 30 · 150 · 2.088</span></span>
<span class="line"><span>  &quot;Socios el día pico de vencimiento&quot;: 5.000 · 30.000 · 360.000</span></span>
<span class="line"><span>  &quot;Técnicos en la calle a la vez&quot;: 10 · 60 · 720</span></span>
<span class="line"><span>  Debajo, en gris: &quot;Escala a 300 cooperativas y 9 millones de suministros sin rediseño&quot;.</span></span>
<span class="line"><span>- Derecha, &quot;Qué tan rápido&quot;: una lista de tiempos con un cronómetro de línea pequeño al lado de cada uno, la cifra en verde y grande:</span></span>
<span class="line"><span>  &quot;0,2 s&quot; abrir una ficha</span></span>
<span class="line"><span>  &quot;0,5 s&quot; buscar un socio</span></span>
<span class="line"><span>  &quot;0,8 s&quot; cobrar en caja (30 cajas a la vez)</span></span>
<span class="line"><span>  &quot;2,5 s&quot; app del socio en un celular de gama baja</span></span>
<span class="line"><span>  &quot;60 min&quot; facturar 50.000 suministros</span></span>
<span class="line"><span>Abajo, una franja gris claro con tres afirmaciones con tilde verde: &quot;Medido con la carga pico&quot; · &quot;Lo pesado de una cooperativa no frena a las demás&quot; · &quot;Cada entrega pasa su prueba de carga&quot;.</span></span>
<span class="line"><span>Pie pequeño: &quot;Perfil de referencia de ingeniería · se recalibra con las mediciones de la cooperativa piloto&quot;.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br></div></div><hr><h2 id="_2-notas-para-el-presentador" tabindex="-1">2. Notas para el presentador <a class="header-anchor" href="#_2-notas-para-el-presentador" aria-label="Permalink to &quot;2. Notas para el presentador&quot;">​</a></h2><ul><li><strong>Son metas de diseño, no mediciones.</strong> Si alguien pregunta &quot;¿ya lo midieron?&quot;, la respuesta es: &quot;Todavía no hay sistema que medir; cada meta tiene su prueba de carga y la primera medición llega con la ola O0&quot;.</li><li><strong>Las metas de facturación masiva</strong> están asumidas con la opción recomendada (PA-NFR-04) y se pueden revisar.</li><li><strong>Dónde va.</strong> Encaja junto a IMG-E08 (&quot;Si ARCA se cae, la cooperativa sigue.&quot;) o después de IMG-T10 (&quot;Lo pesado no frena al usuario.&quot;).</li><li><strong>No sumar los picos.</strong> Los 2.088 empleados y 360.000 socios de la plataforma ya están corregidos por la simultaneidad real (0,6 de la suma de los picos de cada cooperativa); no multiplicar las columnas por cooperativa.</li></ul>`,26)])])}const b=e(i,[["render",t]]);export{m as __pageData,b as default};
